function despachar(ctx, bultoId, { camion }, clave) {    // autorización, lógica y datos: una sola transacción
  db.exec('begin immediate');
  try {
    const previo = db.prepare('select bulto, camion, respuesta from despachos where clave = ?').get(clave);
    if (previo) {
      if (previo.bulto !== bultoId || previo.camion !== camion) throw new ErrorNegocio(422, 'clave-reusada', 'Clave reutilizada', 'Esa clave ya se usó con otro pedido.');
      db.exec('rollback'); ctx.cabeceras = { 'idempotent-replayed': 'true' }; log(ctx, 'info', 'repetición: misma respuesta', { clave });
      return JSON.parse(previo.respuesta);
    }
    const bulto = db.prepare('select * from bultos where id = ?').get(bultoId);
    if (!bulto || bulto.sucursal !== ctx.sucursal) throw new ErrorNegocio(404, 'no-existe', 'No encontrado', 'No existe ese bulto.');
    log(ctx, 'info', 'etapa: autorización', { bulto: bultoId, dueña: bulto.sucursal });
    if (bulto.estado !== 'listo') throw new ErrorNegocio(409, 'estado-invalido', 'Estado inválido', `El bulto está ${bulto.estado}.`);
    const cas = db.prepare('update camiones set cargado_kg = cargado_kg + ? where id = ? and cargado_kg + ? <= capacidad_kg').run(bulto.peso_kg, camion, bulto.peso_kg);
    if (cas.changes === 0) throw new ErrorNegocio(409, 'camion-lleno', 'Camión lleno o inexistente', `${bulto.peso_kg} kg no entran en ${camion}.`);
    db.prepare("update bultos set estado = 'despachado', camion = ? where id = ?").run(camion, bultoId);
    const aviso = `Hola ${bulto.destinatario.trim()}: tu bulto ${bultoId} salió en ${camion}.`;   // falla si destinatario es null
    const cuerpo = { bulto: bultoId, camion, estado: 'despachado' };
    db.prepare('insert into despachos(bulto, camion, clave, respuesta) values (?,?,?,?)').run(bultoId, camion, clave, JSON.stringify(cuerpo));
    db.prepare("insert into jobs(tipo, carga) values ('avisar-destinatario', ?)").run(JSON.stringify({ bulto: bultoId, aviso, destinatario: bulto.destinatario }));
    db.exec('commit'); log(ctx, 'info', 'etapa: datos confirmados', { jobs_nuevos: 1 });
    cache.delete(`ocup:${camion}`);                      // invalidar después de escribir
    return cuerpo;
  } catch (e) { if (db.isTransaction) db.exec('rollback'); throw e; }
}

const servidor = http.createServer(async (req, res) => {
  const ctx = { id: randomUUID().slice(0, 8), ini: performance.now(), cabeceras: {} };
  log(ctx, 'info', 'entrada', { metodo: req.method, ruta: req.url });
  try {
    await recibir(req, ctx); autenticar(req, ctx); log(ctx, 'info', 'etapa: autenticación', { usuario: ctx.usuario });
    const url = new URL(req.url, 'http://x'); let m;
    if ((m = /^\/bultos\/([A-Z]-\d+)\/despachar$/.exec(url.pathname))) {
      if (req.method !== 'POST') throw new ErrorNegocio(405, 'metodo', 'Método no permitido', 'Usá POST.');
      const clave = req.headers['idempotency-key']; if (!clave) throw new ErrorNegocio(400, 'falta-clave', 'Falta la clave', 'Mandá Idempotency-Key.');
      const datos = validar(ctx); log(ctx, 'info', 'etapa: validación', datos);
      const r = despachar(ctx, m[1], datos, clave); responder(res, ctx, 201, r);
    } else if ((m = /^\/camiones\/(CAM-\d+)\/ocupacion$/.exec(url.pathname)) && req.method === 'GET') {
      responder(res, ctx, 200, ocupacion(ctx, m[1]));
    } else throw new ErrorNegocio(404, 'ruta', 'Ruta desconocida', 'No hay nada en esa dirección.');
  } catch (e) {
    if (e instanceof ErrorNegocio) {
      log(ctx, 'warn', `error esperado: ${e.codigo}`, { status: e.status });
      responder(res, ctx, e.status, { type: `https://rumbo.ejemplo.test/errores/${e.codigo}`, title: e.titulo, status: e.status, detail: e.detalle, instance: `/solicitudes/${ctx.id}` }, 'application/problem+json');
    } else {
      log(ctx, 'error', 'error inesperado', { error: String(e), en: (e.stack.split('\n')[1] ?? '').replace(/\(?file:\/\/\S*\//, '').replace(')', '').trim() });   // el detalle va al log…
      responder(res, ctx, 500, { type: 'about:blank', title: 'Error interno', status: 500, detail: 'Algo falló de nuestro lado.', instance: `/solicitudes/${ctx.id}` }, 'application/problem+json');   // …y a la persona, solo el número
    }
  } finally { log(ctx, 'info', 'salida', { status: ctx.status, ms: +(performance.now() - ctx.ini).toFixed(2) }); }
});

